ALTER TABLE app_user ADD COLUMN mfa_secret text, ADD COLUMN mfa_pending_secret text, ADD COLUMN mfa_enabled boolean NOT NULL DEFAULT false;
CREATE TABLE media_asset(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),venue_id uuid NOT NULL REFERENCES venue,outlet_id uuid NOT NULL REFERENCES outlet,path text NOT NULL,mime_type text NOT NULL,width integer NOT NULL,height integer NOT NULL,sha256 text NOT NULL,created_by uuid NOT NULL REFERENCES app_user,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE financial_policy(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),venue_id uuid NOT NULL REFERENCES venue,commission_bps integer NOT NULL DEFAULT 0 CHECK(commission_bps BETWEEN 0 AND 10000),enabled boolean NOT NULL DEFAULT false,effective_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES app_user);
CREATE TABLE job_failure(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_type text NOT NULL,resource_id uuid NOT NULL,attempts integer NOT NULL DEFAULT 1,last_error text NOT NULL,next_attempt_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,UNIQUE(job_type,resource_id));
ALTER TABLE payment_intent ADD COLUMN provider_order_id text UNIQUE;
